    Props (p): id, title, metrics, chart, activity, cols, density. -#}
{%- set v_id = og_def(p['id'], none) -%}
{%- set v_title = og_def(p['title'], none) -%}
{%- set v_metrics = og_def(p['metrics'], none) -%}
{%- set v_chart = og_def(p['chart'], none) -%}
{%- set v_activity = og_def(p['activity'], none) -%}
{%- set v_cols = og_def(p['cols'], '1-2') -%}
{%- set v_density = og_def(p['density'], 'default') -%}
{%- set c_8 -%}
  {%- set c_1 -%}
    {{ og_text(v_title) }}
  {%- endset -%}
  {{ og_include('compose/title.html.j2', {'p': {'As': 2, 'Size': '2xl', 'Weight': 'bold', 'Attrs': og_attrs(['id', og_tpl('{0}-title', [v_id])])}, 'children': c_1}) }}
  {%- if og_t(og_gt(og_len(v_metrics), 0)) %}
    {%- set c_3 -%}
      {%- for v_m in og_l(v_metrics) %}
        {%- set c_2 -%}
          {{ og_include('blocks/stat-tile.html.j2', {'p': {'label': og_get(v_m, ['label']), 'value': og_get(v_m, ['value']), 'icon': og_get(v_m, ['icon']), 'hint': og_get(v_m, ['hint'])}}) }}
        {%- endset -%}
        {{ og_include('compose/box.html.j2', {'p': {'Attrs': og_attrs(['data-slot', 'item'])}, 'children': c_2}) }}
      {%- endfor %}
    {%- endset -%}
    {{ og_include('compose/grid.html.j2', {'p': {'Cols': og_s(v_cols), 'Class': 'gap-4', 'Attrs': og_attrs(['data-slot', 'items'])}, 'children': c_3}) }}
  {%- endif %}
  {%- if og_t(v_activity) %}
    {%- set c_6 -%}
      {%- if og_t(og_gt(og_len(og_get(v_chart, ['series'])), 0)) %}
        {%- set c_4 -%}
          {{ og_include('blocks/bar-chart.html.j2', {'p': {'bars': og_get(v_chart, ['series']), 'label': og_get(v_chart, ['summary']), 'height': 144}}) }}
        {%- endset -%}
        {{ og_include('blocks/panel.html.j2', {'p': {'title': og_get(v_chart, ['title']), 'description': og_get(v_chart, ['text']), 'id': og_tpl('{0}-chart', [v_id]), 'className': og_cnv(['h-full'])}, 'children': og_markup(c_4)}) }}
      {%- endif %}
      {%- if og_t(og_gt(og_len(og_get(v_activity, ['events'])), 0)) %}
        {%- set c_5 -%}
          {{ og_include('blocks/timeline.html.j2', {'p': {'items': og_get(v_activity, ['events'])}}) }}
        {%- endset -%}
        {{ og_include('blocks/panel.html.j2', {'p': {'title': og_get(v_activity, ['title']), 'description': og_get(v_activity, ['text']), 'id': og_tpl('{0}-feed', [v_id]), 'className': og_cnv(['h-full'])}, 'children': og_markup(c_5)}) }}
      {%- endif %}
    {%- endset -%}
    {{ og_include('compose/grid.html.j2', {'p': {'Cols': '1-2', 'Class': 'items-stretch gap-4'}, 'children': c_6}) }}
  {%- elif og_t(og_gt(og_len(og_get(v_chart, ['series'])), 0)) %}
    {%- set c_7 -%}
      {{ og_include('blocks/bar-chart.html.j2', {'p': {'bars': og_get(v_chart, ['series']), 'label': og_get(v_chart, ['summary']), 'height': 144}}) }}
    {%- endset -%}
    {{ og_include('blocks/panel.html.j2', {'p': {'title': og_get(v_chart, ['title']), 'description': og_get(v_chart, ['text']), 'id': og_tpl('{0}-chart', [v_id]), 'className': og_cnv(['h-full'])}, 'children': og_markup(c_7)}) }}
  {%- endif %}
{%- endset -%}
{{ og_include('compose/stack.html.j2', {'p': {'Gap': og_s(('4' if og_t(og_eq(v_density, 'compact')) else '6')), 'Align': 'stretch', 'Class': 'min-w-0', 'Attrs': og_attrs(['data-slot', 'app-main'])}, 'children': c_8}) }}
